<script lang="ts">import type { RunEvent } from '$lib/types'; let { events = [], goalError = '' }: { events?: RunEvent[]; goalError?: string } = $props(); const stamp=(value:number)=>new Date(value).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}); const long=(v:string)=>v.length>1200; const preview=(v:string)=>v.slice(0,360)+(v.length>360?'…':'');</script>
<section class="timeline" aria-label="Timeline">{#if goalError}<details class="error"><summary>Goal status unavailable</summary><p>{goalError}</p></details>{/if}{#each events as event (event.id)}<article class={event.kind}><time>{stamp(event.createdAt)}</time><div><b>{event.title}</b>{#if event.detail}{#if long(event.detail)}<p>{preview(event.detail)}</p><details><summary aria-label={`Show full detail for ${event.title || "timeline event"}`}>Show full detail · {event.detail.length} characters</summary><!-- svelte-ignore a11y_no_noninteractive_tabindex (scrollable diagnostic output must be keyboard reachable) -->
<pre tabindex="0" aria-label={`Full detail for ${event.title || "timeline event"}`}>{event.detail}</pre></details>{:else}<p>{event.detail}</p>{/if}{/if}</div></article>{:else}<p class="empty">Run events will appear here as the CLI reports them.</p>{/each}</section>
<style>.timeline{overflow:auto;padding:10px;min-width:0}.timeline article{display:grid;grid-template-columns:48px minmax(0,1fr);gap:8px;padding:7px 0;border-bottom:1px solid var(--line);font-size:11px;min-width:0}.timeline time{color:var(--muted);font:10px var(--mono)}.timeline p,.timeline pre{margin:3px 0;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;min-width:0}.timeline pre{max-height:240px;overflow:auto;padding:7px;background:var(--soft)}.timeline summary{cursor:pointer;color:var(--muted);font-size:10px}.empty,.error{color:var(--muted);font-size:11px}.error,.error b{color:#b54a55}.tool b{color:var(--accent-ink)}</style>
